class Solution:
    def findMin(self, nums: list[int]) -> int:
        ans = nums[0]
        for x in nums:
            if x < ans:
                ans = x
        return ans

solutions.better:
class Solution:
    def findMin(self, nums: list[int]) -> int:
        arr = []
        for x in nums:
            if not arr or arr[-1] != x:
                arr.append(x)
        lo, hi = 0, len(arr) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] > arr[hi]:
                lo = mid + 1
            else:
                hi = mid
        return arr[lo]

